CLASS zcl_interactive_flight_html DEFINITION PUBLIC FINAL CREATE PUBLIC.
  PUBLIC SECTION.
    TYPES: BEGIN OF ty_sflight,
             carrid   TYPE sflight-carrid,
             connid   TYPE sflight-connid,
             fldate   TYPE sflight-fldate,
             price    TYPE sflight-price,
             currency TYPE sflight-currency,
           END OF ty_sflight.
    TYPES tt_sflight TYPE STANDARD TABLE OF ty_sflight WITH EMPTY KEY.

    METHODS display_filtered_flights
      IMPORTING
        iv_min_price TYPE sflight-price OPTIONAL
        iv_currency  TYPE sflight-currency OPTIONAL.
ENDCLASS.

CLASS zcl_interactive_flight_html IMPLEMENTATION.
  METHOD display_filtered_flights.
    DATA lt_flights TYPE tt_sflight.

    SELECT carrid, connid, fldate, price, currency
      FROM sflights
      INTO TABLE @lt_flights
      UP TO 50 ROWS. " More rows for sorting demo

    IF iv_min_price IS SUPPLIED AND iv_min_price > 0.
      lt_flights = FILTER #( lt_flights WHERE price >= iv_min_price ).
    ENDIF.

    IF iv_currency IS SUPPLIED AND iv_currency IS NOT INITIAL.
      lt_flights = FILTER #( lt_flights WHERE currency = iv_currency ).
    ENDIF.

    DATA(lv_html_header) = `
          <!DOCTYPE html>
          <html>
          <head>
            <title>Filtered Flights</title>
            <style>
              table { width: 100%; border-collapse: collapse; margin-top: 20px; }
              th, td { border: 1px solid black; padding: 8px; text-align: left; }
              th { background-color: #f2f2f2; cursor: pointer; }
              h1 { color: #333; }
            </style>
            <script>
              function sortTable(n) {
                var table, rows, switching, i, x, y, shouldSwitch, dir, switchcount = 0;
                table = document.getElementById("flightTable");
                switching = true;
                dir = "asc";
                while (switching) {
                  switching = false;
                  rows = table.rows;
                  for (i = 1; i < (rows.length - 1); i++) {
                    shouldSwitch = false;
                    x = rows[i].getElementsByTagName("TD")[n];
                    y = rows[i + 1].getElementsByTagName("TD")[n];
                    var xContent = isNaN(x.innerHTML) ? x.innerHTML.toLowerCase() : parseFloat(x.innerHTML);
                    var yContent = isNaN(y.innerHTML) ? y.innerHTML.toLowerCase() : parseFloat(y.innerHTML);

                    if (dir == "asc") {
                      if (xContent > yContent) {
                        shouldSwitch = true;
                        break;
                      }
                    } else if (dir == "desc") {
                      if (xContent < yContent) {
                        shouldSwitch = true;
                        break;
                      }
                    }
                  }
                  if (shouldSwitch) {
                    rows[i].parentNode.insertBefore(rows[i + 1], rows[i]);
                    switching = true;
                    switchcount ++;
                  } else {
                    if (switchcount == 0 && dir == "asc") {
                      dir = "desc";
                      switching = true;
                    }
                  }
                }
              }
            </script>
          </head>
          <body>
            <h1>Filtered Flights</h1>
            <table id="flightTable">
              <thead>
                <tr>
                  <th onclick="sortTable(0)">Carrier ID</th>
                  <th onclick="sortTable(1)">Connection ID</th>
                  <th onclick="sortTable(2)">Flight Date</th>
                  <th onclick="sortTable(3)">Price</th>
                  <th onclick="sortTable(4)">Currency</th>
                </tr>
              </thead>
              <tbody>`. 

    DATA(lv_html_rows) = REDUCE string(
      INIT html_rows = ``
      FOR flight IN lt_flights
      NEXT html_rows = html_rows && `
            <tr>
              <td>` && flight-carrid   && `</td>
              <td>` && flight-connid   && `</td>
              <td>` && flight-fldate   && `</td>
              <td>` && flight-price    && `</td>
              <td>` && flight-currency && `</td>
            </tr>`
    ).

    DATA(lv_html_footer) = `
              </tbody>
            </table>
          </body>
          </html>`.

    DATA(lv_full_html) = lv_html_header && lv_html_rows && lv_html_footer.

    cl_abap_browser=>show_html(
      EXPORTING
        html_xstring = cl_abap_conv_codepage=>create_out( )->convert( lv_full_html )
        title        = 'Interactive Flight Overview'
        size         = cl_abap_browser=>default_size
    ).
  ENDMETHOD.
ENDCLASS.
